Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
iio:imu:adis16480: fix buffering for devices with no burst
 mode
MIME-Version: 1.0
Content-Type: text/plain; charset=UTF-8
Content-Transfer-Encoding: 8bit

The trigger handler defined in the driver assumes that burst mode is
being used. Hence, for devices that do not support it, we have to use
the adis library default trigger implementation.

Tested-by: Julia Pineda <julia.pineda@analog.com>
Fixes: 941f130881fa9 ("iio: adis16480: support burst read function")
Signed-off-by: Nuno Sá <nuno.sa@analog.com>
Link: https://lore.kernel.org/r/20220114132608.241-1-nuno.sa@analog.com
Cc: <Stable@vger.kernel.org>
Signed-off-by: Jonathan Cameron <Jonathan.Cameron@huawei.com>

Here is the root cause:
The bug arises from the assumption in the trigger handler of the `adis16480` driver that all devices support burst mode. This leads to incorrect behavior for devices that do not have burst mode capability, as the driver attempts to use a trigger handler that is not applicable, resulting in potential failures in data buffering and retrieval.

Here is the patch:

 static int adis16480_probe(struct spi_device *spi)
 {
 	const struct spi_device_id *id = spi_get_device_id(spi);
 	const struct adis_data *adis16480_data;
+	irq_handler_t trigger_handler = NULL;
 	struct iio_dev *indio_dev;
 	struct adis16480 *st;
 	int ret;

 	indio_dev = devm_iio_device_alloc(&spi->dev, sizeof(*st));
 	if (indio_dev == NULL)
 		return -ENOMEM;

 	st = iio_priv(indio_dev);

 	st->chip_info = &adis16480_chip_info[id->driver_data];
 	indio_dev->name = spi_get_device_id(spi)->name;
 	indio_dev->channels = st->chip_info->channels;
 	indio_dev->num_channels = st->chip_info->num_channels;
 	indio_dev->info = &adis16480_info;
 	indio_dev->modes = INDIO_DIRECT_MODE;

 	adis16480_data = &st->chip_info->adis_data;

 	ret = adis_init(&st->adis, indio_dev, spi, adis16480_data);
 	if (ret)
 		return ret;

 	ret = __adis_initial_startup(&st->adis);
 	if (ret)
 		return ret;

 	if (st->chip_info->has_sleep_cnt) {
 		ret = devm_add_action_or_reset(&spi->dev, adis16480_stop,
 					       indio_dev);
 		if (ret)
 			return ret;
 	}

 	ret = adis16480_config_irq_pin(spi->dev.of_node, st);
 	if (ret)
 		return ret;

 	ret = adis16480_get_ext_clocks(st);
 	if (ret)
 		return ret;

 	if (!IS_ERR_OR_NULL(st->ext_clk)) {
 		ret = adis16480_ext_clk_config(st, spi->dev.of_node, true);
 		if (ret)
 			return ret;

 		ret = devm_add_action_or_reset(&spi->dev, adis16480_clk_disable, st->ext_clk);
 		if (ret)
 			return ret;

 		st->clk_freq = clk_get_rate(st->ext_clk);
 		st->clk_freq *= 1000; /* micro */
 		if (st->clk_mode == ADIS16480_CLK_PPS) {
 			u16 sync_scale;

 			/*
 			 * In PPS mode, the IMU sample rate is the clk_freq * sync_scale. Hence,
 			 * default the IMU sample rate to the highest multiple of the input clock
 			 * lower than the IMU max sample rate. The internal sample rate is the
 			 * max...
 			 */
 			sync_scale = st->chip_info->int_clk / st->clk_freq;
 			ret = __adis_write_reg_16(&st->adis, ADIS16495_REG_SYNC_SCALE, sync_scale);
 			if (ret)
 				return ret;
 		}
 	} else {
 		st->clk_freq = st->chip_info->int_clk;
 	}

+	/* Only use our trigger handler if burst mode is supported */
+	if (adis16480_data->burst_len)
+		trigger_handler = adis16480_trigger_handler;
+
 	ret = devm_adis_setup_buffer_and_trigger(&st->adis, indio_dev,
-						 adis16480_trigger_handler);
+						 trigger_handler);
 	if (ret)
 		return ret;

 	ret = devm_iio_device_register(&spi->dev, indio_dev);
 	if (ret)
 		return ret;

 	adis16480_debugfs_init(indio_dev);

 	return 0;
 }



